from django.core.management.base import BaseCommand
from monitoring.models import Product, Store

PRODUCTS = [
('Масло подсолнечное','л','Бакалея'),('Картофель','кг','Овощи и фрукты'),('Морковь','кг','Овощи и фрукты'),('Лук репчатый','кг','Овощи и фрукты'),('Капуста белокочанная','кг','Овощи и фрукты'),('Сахар-песок','кг','Бакалея'),('Крупа гречневая','кг','Бакалея'),('Мука пшеничная первого сорта','кг','Бакалея'),('Хлеб пшеничный из муки первого сорта','шт','Хлеб и выпечка'),('Макаронные изделия (рожки)','кг','Бакалея'),('Говядина на кости','кг','Мясо и рыба'),('Говядина без кости','кг','Мясо и рыба'),('Конина (включая бескостное мясо)','кг','Мясо и рыба'),('Баранина (включая бескостное мясо)','кг','Мясо и рыба'),('Курица','кг','Мясо и рыба'),('Мясной фарш','кг','Мясо и рыба'),('Рыба свежая, охлаждённая или мороженая','кг','Мясо и рыба'),('Сыр твёрдый и полутвёрдый','кг','Молочные продукты'),('Творог жирностью 5–9%','кг','Молочные продукты'),('Сметана','кг','Молочные продукты'),('Кефир жирностью 2–3%','л','Молочные продукты'),('Яйца первой категории','10 шт','Молочные продукты'),('Масло сливочное','кг','Молочные продукты'),('Яблоки','кг','Овощи и фрукты'),('Огурцы','кг','Овощи и фрукты'),('Помидоры','кг','Овощи и фрукты'),('Соль (кроме экстра)','кг','Бакалея'),('Чай чёрный','кг','Бакалея'),('Рис шлифованный','кг','Бакалея'),('Мясо кур (бедро, голень, окорочок)','кг','Мясо и рыба'),('Молоко (пастеризованное, ультрапастеризованное, стерилизованное)','л','Молочные продукты'),
]
STORES = [
('Торговая точка из ссылки 2GIS','Адрес и название в ссылке не указаны','Кызылорда',44.824059,65.525261,'https://2gis.kz/kyzylorda/branches/70000001062790591/geo/70030076350383921/65.525261%2C44.824059?m=65.517399%2C44.82818%2F13.33'),
]
OLD_PLACEHOLDERS = ['Дәмді Market', 'Ақмешіт супермаркет', 'Сырдария дүкені', 'Береке', 'Үй жанындағы дүкен', 'Торговая точка из 2ГИС']

class Command(BaseCommand):
    help = 'Загружает каталог СЗПТ и подтверждённую пользователем точку 2GIS без цен.'
    def handle(self, *args, **options):
        for name, unit, category in PRODUCTS:
            Product.objects.update_or_create(name=name, defaults={'unit': unit, 'category': category, 'is_active': True})
        Store.objects.filter(name__in=OLD_PLACEHOLDERS).update(is_active=False)
        for name, address, district, latitude, longitude, source_url in STORES:
            Store.objects.update_or_create(name=name, defaults={'address': address, 'district': district, 'latitude': latitude, 'longitude': longitude, 'source_url': source_url, 'is_active': True})
        self.stdout.write(self.style.SUCCESS(f'Загружено {len(PRODUCTS)} товаров и {len(STORES)} магазинов. Цены не заданы.'))
